import type { Metadata } from "next";
import { Be_Vietnam_Pro } from "next/font/google";
import "./globals.css";
import { Toaster } from "@/components/ui/toaster";
import { ThemeProvider } from "@/components/theme-provider";

const beVietnamPro = Be_Vietnam_Pro({
  variable: "--font-be-vietnam",
  subsets: ["latin", "vietnamese"],
  weight: ["300", "400", "500", "600", "700", "800"],
});

export const metadata: Metadata = {
  title: "EQUIDELI — Hệ thống quản lý vận chuyển ngựa đua xuyên biên giới",
  description:
    "EQUIDELI — Nền tảng quản lý vận chuyển ngựa đua quốc tế: tạo yêu cầu, thẩm định hồ sơ pháp lý, lập kế hoạch lộ trình và theo dõi hành trình.",
  keywords: ["EQUIDELI", "vận chuyển ngựa đua", "kiểm dịch", "thông quan", "logistics ngựa"],
  authors: [{ name: "EQUIDELI Team" }],
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="vi" suppressHydrationWarning>
      <head>
        {/* Prevent FOUC: apply theme before hydration */}
        <script
          dangerouslySetInnerHTML={{
            __html: `(function(){try{var t=localStorage.getItem('equideli-theme');if(t==='dark'||(!t&&window.matchMedia('(prefers-color-scheme: dark)').matches)){document.documentElement.classList.add('dark')}}catch(e){}})()`,
          }}
        />
      </head>
      <body
        className={`${beVietnamPro.variable} font-sans antialiased bg-background text-foreground`}
      >
        <ThemeProvider>{children}</ThemeProvider>
        <Toaster />
      </body>
    </html>
  );
}
